94	typedef struct _WaylandEventSource
95	{
96	  GSource source;
97	  GPollFD pfd;
98	  uint32_t mask;
99	  struct wl_display *display;
100	  struct wl_event_queue *queue;
101	  gboolean reading;
102	} WaylandEventSource;
